// Package source owns source-file boundary detection helpers.
//
// One boundary is generated code: a Go file whose leading comments say both generated and do not edit is skipped unless --include-ignored is set.
// A Go file that cannot be read is never marked generated by its header.
package source

import (
	"bufio"
	"os"
	"strings"
)

// HasGeneratedGoHeader returns whether source's leading comments have both markers, stopping at a trimmed "package " prefix outside block comments.
// Scanning also stops at EOF or bufio.Scanner's default token-size limit and checks only the comments collected so far.
//
// The marker needs both "generated" and "do not edit", in any letter case, somewhere in the leading comments.
// Ordinary prose that says only one of those phrases stays in scope for analysis.
//
// It reports false for empty source or any nonblank, non-comment line without the "package " prefix, even after both markers.
// A line opening with /* is kept whole, so text after that comment on the same line, even a package clause, also counts.
func HasGeneratedGoHeader(source string) bool {
	scanner := bufio.NewScanner(strings.NewReader(source))
	inBlockComment := false
	var leadingComments strings.Builder
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		if inBlockComment {
			leadingComments.WriteByte('\n')
			leadingComments.WriteString(line)
			if strings.Contains(line, "*/") {
				inBlockComment = false
			}
			continue
		}
		// A package clause starting its own line ends the search, so a do-not-edit note further down a hand-written file leaves it in scope.
		if strings.HasPrefix(line, "package ") {
			break
		}
		switch {
		case strings.HasPrefix(line, "//"):
			leadingComments.WriteByte('\n')
			leadingComments.WriteString(strings.TrimSpace(strings.TrimPrefix(line, "//")))
		case strings.HasPrefix(line, "/*"):
			leadingComments.WriteByte('\n')
			leadingComments.WriteString(line)
			if !strings.Contains(line[2:], "*/") {
				inBlockComment = true
			}
		// Any code line before the package clause, which only a malformed or non-Go file has, ends the search and the file counts as hand-written.
		default:
			return false
		}
	}
	lower := strings.ToLower(leadingComments.String())
	return strings.Contains(lower, "generated") && strings.Contains(lower, "do not edit")
}

// isGeneratedGo reads the Go file at path and applies the shared generated-code header contract.
//
// It reports true when HasGeneratedGoHeader finds both the generated and do not edit markers in the file's leading comments.
// It reports false when os.ReadFile fails on path, such as a file deleted mid-run, so an unreadable file is never classed as generated.
func isGeneratedGo(path string) bool {
	// #nosec G304 -- scanner intentionally opens files selected by discovery.
	data, err := os.ReadFile(path)
	if err != nil {
		return false
	}
	return HasGeneratedGoHeader(string(data))
}
